extension DocumentParserTests {

    static func testHtmlDocument(
        url: URL,
        createdAt: Date,
        updatedAt: Date
    ) -> Document {
        .init(
            id: nil,
            url: url,
            fileFormat: .html,
            content: "<html><body>Hello, World!</body></html>",
            checksum: "2cefa59fe9324e28e882c81dbf26194daa13151694fc6e67d3a8d9cb8402bef6",
            projectID: 0,
            embeddings: [
                .init(
                    chunk: "<html><body>Hello, World!</body></html>",
                    embedding: Self.testHtmlEmbeddingValues
                )
            ],
            createdAt: createdAt,
            updatedAt: updatedAt
        )
    }

    static func testTxtDocument(
        url: URL,
        createdAt: Date,
        updatedAt: Date
    ) -> Document {
        .init(
            id: nil,
            url: url,
            fileFormat: .txt,
            content: "Hello, World!",
