            projectID: 0,
            embeddings: [
                .init(
                    chunk: "Hello, World!",
                    embedding: Self.testTxtEmbeddingValues
                )
            ],
            createdAt: createdAt,
            updatedAt: updatedAt
        )
    }

    static func testMdDocument(
        url: URL,
        createdAt: Date,
        updatedAt: Date
    ) -> Document {
        .init(
            id: nil,
            url: url,
            fileFormat: .md,
            content: "## Hello, World!",
