        )
    }

    static func testPdfDocument(
        url: URL,
        createdAt: Date,
        updatedAt: Date
    ) -> Document {
        .init(
            id: nil,
            url: url,
            fileFormat: .pdf,
            content: "This is a test PDF document.\nIf you can read this, you have Adobe Acrobat Reader installed on your computer.",
